class ProductJdbcDao implements ProductDao {
  public Product save(Product p) { /* INSERT + RETURN_GENERATED_KEYS */ return null; }
  public Optional<Product> findById(Long id) { /* SELECT WHERE id=? */ return Optional.empty(); }
  public List<Product> findAll() { /* SELECT * */ return List.of(); }
  public void deleteById(Long id) { /* DELETE */ }
}

class ProductInMemoryDao implements ProductDao {
  Map<Long, Product> storage = new HashMap<>();
  AtomicLong seq = new AtomicLong(1);
  public Product save(Product p) { long id = seq.getAndIncrement(); Product withId = new Product(id, p.name(), p.price()); storage.put(id, withId); return withId; }
  public Optional<Product> findById(Long id) { return Optional.ofNullable(storage.get(id)); }
  public List<Product> findAll() { return new ArrayList<>(storage.values()); }
  public void deleteById(Long id) { storage.remove(id); }
}

static void printAllProducts(ProductDao dao) {
